1	// Package settings provides configuration loading for Entire.
2	// This package is separate from cli to allow strategy package to import it
3	// without creating an import cycle (cli imports strategy).
4	package settings
5	
6	import (
7		"bytes"
8		"context"
9		"encoding/json"
10		"fmt"
11		"os"
12		"path/filepath"
13		"strconv"
14		"strings"
15		"sync"
16		"time"
17	
18		"github.com/entireio/cli/cmd/entire/cli/jsonutil"
19		"github.com/entireio/cli/cmd/entire/cli/paths"
20	)
21	
22	const (
23		// EntireSettingsFile is the path to the Entire settings file
24		EntireSettingsFile = ".entire/settings.json"
25		// EntireSettingsLocalFile is the path to the local settings override file (not committed)
26		EntireSettingsLocalFile = ".entire/settings.local.json"
27		// defaultGenerationRetentionDays is the default retention window for archived
28		// checkpoints v2 raw-transcript generations when no override is configured.
29		defaultGenerationRetentionDays = 60
30	)
31	
32	var checkpointsVersionWarningOnce sync.Once
33	
34	// Commit linking mode constants.
35	const (
36		// CommitLinkingAlways auto-links commits to sessions without prompting.
37		CommitLinkingAlways = "always"
38		// CommitLinkingPrompt prompts the user on each commit (default for existing users).
39		CommitLinkingPrompt = "prompt"
40	)
41	
42	// EntireSettings represents the .entire/settings.json configuration
43	type EntireSettings struct {
44		// Enabled indicates whether Entire is active. When false, CLI commands
45		// show a disabled message and hooks exit silently. Defaults to true.
46		Enabled bool `json:"enabled"`
47	
48		// LocalDev indicates whether to use "go run" instead of the "entire" binary
49		// This is used for development when the binary is not installed
50		LocalDev bool `json:"local_dev,omitempty"`
51	
52		// LogLevel sets the logging verbosity (debug, info, warn, error).
53		// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
54		// Defaults to "info".
55		LogLevel string `json:"log_level,omitempty"`
56	
57		// StrategyOptions contains strategy-specific configuration
58		StrategyOptions map[string]any `json:"strategy_options,omitempty"`
59	
60		// AbsoluteGitHookPath embeds the full binary path in git hooks instead of
61		// bare "entire". This is needed for GUI git clients (Xcode, Tower, etc.)
62		// that don't source shell profiles and can't find "entire" on PATH.
63		AbsoluteGitHookPath bool `json:"absolute_git_hook_path,omitempty"`
64	
65		// Telemetry controls anonymous usage analytics.
66		// nil = not asked yet (show prompt), true = opted in, false = opted out
67		Telemetry *bool `json:"telemetry,omitempty"`
68	
69		// Redaction configures PII redaction behavior for transcripts and metadata.
70		Redaction *RedactionSettings `json:"redaction,omitempty"`
71	
72		// CommitLinking controls how commits are linked to agent sessions.
73		// "always" = auto-link without prompting, "prompt" = ask on each commit.
74		// Defaults to "prompt" (preserves existing user behavior).
75		CommitLinking string `json:"commit_linking,omitempty"`
76	
77		// ExternalAgents enables discovery and registration of external agent
78		// plugins (entire-agent-* binaries on $PATH). Defaults to false.
79		ExternalAgents bool `json:"external_agents,omitempty"`
80	
81		// SummaryGeneration stores provider preferences for explain --generate.
82		// This is separate from strategy_options.summarize, which controls
83		// checkpoint auto-summarize behavior.
84		SummaryGeneration *SummaryGenerationSettings `json:"summary_generation,omitempty"`
85	
86		// Vercel indicates that the repository uses Vercel and the metadata branch
87		// should include a vercel.json that disables deployments for Entire branches.
88		Vercel bool `json:"vercel,omitempty"`
89	
90		// SummaryTimeoutSeconds is an optional hard deadline (in seconds) for
91		// `entire explain --generate` summary generation. Zero or negative means
92		// "unset" -- the caller picks the default. Not yet consumed by the
93		// generate path; present so settings round-trip for a follow-up change
94		// that wires it into the deadline selection.
95		SummaryTimeoutSeconds int `json:"summary_timeout_seconds,omitempty"`
96	
97		// SignCheckpointCommits controls whether checkpoint commits are signed.
98		// nil/true = sign (default), false = skip signing.
99		SignCheckpointCommits *bool `json:"sign_checkpoint_commits,omitempty"`
100	
101		// Deprecated: no longer used. Exists to tolerate old settings files
102		// that still contain "strategy": "auto-commit" or similar.
103		Strategy string `json:"strategy,omitempty"`
104	}
105	
106	// SummaryGenerationSettings configures provider selection for on-demand
107	// checkpoint summaries generated by explain --generate.
108	type SummaryGenerationSettings struct {
109		// Provider is the selected summary provider agent name
110		// (for example "claude-code", "codex", or "gemini").
111		Provider string `json:"provider,omitempty"`
112	
113		// Model is an optional model hint passed to the selected provider.
114		Model string `json:"model,omitempty"`
115	}
116	
117	// Validate returns an error if the settings combination is semantically invalid.
118	// A model without a provider is meaningless: the model hint needs a provider to
119	// route to. The load path calls Validate() after merging, catching hand-edited
120	// files that land in this state.
121	func (s *SummaryGenerationSettings) Validate() error {
122		if s == nil {
123			return nil
124		}
125		if s.Model != "" && s.Provider == "" {
126			return fmt.Errorf("summary_generation.model %q set without summary_generation.provider", s.Model)
127		}
128		return nil
129	}
130	
131	// SetProvider updates the provider and optionally the model, clearing any stale
132	// model from the previous provider when switching without a replacement.
133	// An empty newProvider preserves the current provider; an empty newModel
134	// preserves the current model unless the provider is changing, in which case
135	// the old model is cleared to avoid passing (say) a Claude model to Codex.
136	func (s *SummaryGenerationSettings) SetProvider(newProvider, newModel string) {
137		if s == nil {
138			return
139		}
140		if newProvider != "" && s.Provider != "" && s.Provider != newProvider && newModel == "" {
141			s.Model = ""
142		}
143		if newProvider != "" {
144			s.Provider = newProvider
145		}
146		if newModel != "" {
147			s.Model = newModel
148		}
149	}
150	
151	// RedactionSettings configures redaction behavior beyond the default secret detection.
152	type RedactionSettings struct {
153		PII *PIISettings `json:"pii,omitempty"`
154	}
155	
156	// PIISettings configures PII detection categories.
157	// When Enabled is true, email and phone default to true; address defaults to false.
158	type PIISettings struct {
159		Enabled        bool              `json:"enabled"`
160		Email          *bool             `json:"email,omitempty"`
161		Phone          *bool             `json:"phone,omitempty"`
162		Address        *bool             `json:"address,omitempty"`
163		CustomPatterns map[string]string `json:"custom_patterns,omitempty"`
164	}
165	
166	// GetCommitLinking returns the effective commit linking mode.
167	// Returns the explicit value if set, otherwise defaults to "prompt"
168	// to preserve existing user behavior.
169	func (s *EntireSettings) GetCommitLinking() string {
170		if s.CommitLinking != "" {
171			return s.CommitLinking
172		}
173		return CommitLinkingPrompt
174	}
175	
176	// SummaryTimeoutValue returns the configured hard deadline for
177	// `entire explain --generate` summary generation. Zero means "unset" --
178	// the caller picks the default. Negative values are treated as unset.
179	func (s *EntireSettings) SummaryTimeoutValue() time.Duration {
180		if s.SummaryTimeoutSeconds < 1 {
181			return 0
182		}
183		return time.Duration(s.SummaryTimeoutSeconds) * time.Second
184	}
185	
186	// Load loads the Entire settings from .entire/settings.json,
187	// then applies any overrides from .entire/settings.local.json if it exists.
188	// Returns default settings if neither file exists.
189	// Works correctly from any subdirectory within the repository.
190	func Load(ctx context.Context) (*EntireSettings, error) {
191		// Get absolute paths for settings files
192		settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
193		if err != nil {
194			settingsFileAbs = EntireSettingsFile // Fallback to relative
195		}
196		localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
197		if err != nil {
198			localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
199		}
200	
201		return loadMergedSettings(settingsFileAbs, localSettingsFileAbs)
202	}
203	
204	func loadMergedSettings(settingsFileAbs, localSettingsFileAbs string) (*EntireSettings, error) {
205		// Load base settings
206		settings, err := loadFromFile(settingsFileAbs)
207		if err != nil {
208			return nil, fmt.Errorf("reading settings file: %w", err)
209		}
210	
211		// Apply local overrides if they exist
212		localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
213		if err != nil {
214			if !os.IsNotExist(err) {
215				return nil, fmt.Errorf("reading local settings file: %w", err)
216			}
217			// Local file doesn't exist, continue without overrides
218		} else {
219			if err := mergeJSON(settings, localData); err != nil {
220				return nil, fmt.Errorf("merging local settings: %w", err)
221			}
222		}
223	
224		// Re-validate after merge. Individual files are validated by loadFromFile,
225		// but mergeJSON patches fields independently and can produce combinations
226		// (e.g. model without provider when the local override sets only a model
227		// on top of a base with no provider) that neither file alone contained.
228		if err := settings.SummaryGeneration.Validate(); err != nil {
229			return nil, fmt.Errorf("merged settings invalid: %w", err)
230		}
231	
232		return settings, nil
233	}
