			name: "vercel → features.vercel",
			legacy: &EntireSettings{
				Enabled: true,
				Vercel:  true,
			},
			check: func(t *testing.T, got *Settings) {
				if !got.Features.Vercel {
					t.Fatal("Features.Vercel = false, want true")
				}
			},
		},
