1	// This file implements LoadV2 and the legacy → v2 synthesizer.
2	//
3	// Loading rules:
4	//   - If .entire/settings.json declares "schema": 2, the file is parsed
5	//     directly as Settings. A local override file, if present, must also
6	//     declare "schema": 2 (mixed-shape settings are rejected with a
7	//     descriptive error).
8	//   - Otherwise, the legacy Load() path runs and its EntireSettings result
9	//     is mapped into Settings via synthesizeFromLegacy.
10	//
11	// The synthesizer is the single source of truth for legacy → v2 mapping
12	// and is the implementation that `entire migrate-config` will reuse to
13	// rewrite settings.json into the new shape.
14	
15	package settings
16	
17	import (
18		"bytes"
19		"context"
20		"encoding/json"
21		"errors"
22		"fmt"
23		"os"
24	
25		"github.com/entireio/cli/cmd/entire/cli/paths"
26	)
27	
28	// Backend type constants used in BackendConfig.Type.
29	const (
30		BackendTypeV1    = "v1"
31		BackendTypeV2    = "v2"
32		BackendTypeGmeta = "gmeta"
33	)
34	
35	// LoadV2 loads settings as the v2 shape. Files declaring "schema": 2 are
36	// parsed natively; older files are loaded via the legacy parser and
37	// synthesized. The local override file is merged the same way.
38	//
39	// Returns Settings with sensible defaults populated (Schema=2, Enabled=true)
40	// if neither settings file exists.
41	func LoadV2(ctx context.Context) (*Settings, error) {
42		mainAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
43		if err != nil {
44			mainAbs = EntireSettingsFile
45		}
46		localAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
47		if err != nil {
48			localAbs = EntireSettingsLocalFile
49		}
50	
51		mainData, mainErr := readSettingsFileIfExists(mainAbs)
52		if mainErr != nil {
53			return nil, fmt.Errorf("reading settings file: %w", mainErr)
54		}
55		localData, localErr := readSettingsFileIfExists(localAbs)
56		if localErr != nil {
57			return nil, fmt.Errorf("reading local settings file: %w", localErr)
58		}
59	
60		mainIsV2 := isSchemaV2(mainData)
61		localIsV2 := isSchemaV2(localData)
62	
63		switch {
64		case mainData == nil && localData == nil:
65			return defaultSettings(), nil
66	
67		case mixedShapesRejected(mainData, localData, mainIsV2, localIsV2):
68			return nil, errors.New("mixed schema versions in settings files; run `entire migrate-config` to convert all settings to schema 2")
69	
70		case mainIsV2 || localIsV2:
71			return loadFromV2Files(mainData, localData)
72	
73		default:
74			// Both files (if present) are legacy shape. Defer to the legacy
75			// loader to handle merging, then synthesize into v2.
76			legacy, err := loadMergedSettings(mainAbs, localAbs)
77			if err != nil {
78				return nil, err
79			}
80			return synthesizeFromLegacy(legacy), nil
81		}
82	}
83	
84	// LoadV2FromBytes parses a single settings document from raw bytes.
85	// Accepts either schema-v2 JSON or legacy JSON; the shape is auto-detected
86	// via the schema field. No local-override merge is performed.
87	func LoadV2FromBytes(data []byte) (*Settings, error) {
88		if len(data) == 0 {
89			return defaultSettings(), nil
90		}
91		if isSchemaV2(data) {
92			return parseV2Bytes(data)
93		}
94		legacy, err := LoadFromBytes(data)
95		if err != nil {
96			return nil, err
97		}
98		return synthesizeFromLegacy(legacy), nil
99	}
100	
101	// readSettingsFileIfExists returns the file contents, or (nil, nil) if the
102	// file does not exist. Other I/O errors propagate.
103	func readSettingsFileIfExists(path string) ([]byte, error) {
104		data, err := os.ReadFile(path) //nolint:gosec // path is from AbsPath or constant
105		if err != nil {
106			if os.IsNotExist(err) {
107				return nil, nil
108			}
109			return nil, err //nolint:wrapcheck // caller wraps with file context
110		}
111		return data, nil
112	}
113	
114	// isSchemaV2 reports whether a settings JSON document declares schema >= 2.
115	// Returns false for nil/empty input or invalid JSON; callers handle those
116	// cases explicitly downstream.
117	func isSchemaV2(data []byte) bool {
118		if len(data) == 0 {
119			return false
120		}
121		var probe struct {
122			Schema int `json:"schema"`
123		}
124		if err := json.Unmarshal(data, &probe); err != nil {
125			return false
126		}
127		return probe.Schema >= CurrentSchemaVersion
128	}
129	
130	// mixedShapesRejected reports the only configuration we treat as an error:
131	// exactly one of (main, local) declares schema 2 while the other is legacy.
132	// Two missing files or two same-shape files are both fine.
133	func mixedShapesRejected(mainData, localData []byte, mainIsV2, localIsV2 bool) bool {
134		bothPresent := mainData != nil && localData != nil
135		return bothPresent && (mainIsV2 != localIsV2)
136	}
137	
138	// loadFromV2Files parses one or both files as schema-v2 JSON and applies the
139	// local override on top of the main settings. At least one of the inputs is
140	// guaranteed by the caller to be a v2 document.
141	func loadFromV2Files(mainData, localData []byte) (*Settings, error) {
142		settings := defaultSettings()
143		if mainData != nil {
144			parsed, err := parseV2Bytes(mainData)
145			if err != nil {
146				return nil, fmt.Errorf("parsing settings file: %w", err)
147			}
148			settings = parsed
149		}
150		if localData != nil {
151			if err := mergeV2Override(settings, localData); err != nil {
152				return nil, fmt.Errorf("merging local settings: %w", err)
153			}
154		}
155		return settings, nil
156	}
157	
158	// parseV2Bytes parses a single schema-v2 JSON document into Settings.
159	// Strict decoding rejects unknown fields so typos become loud failures.
160	func parseV2Bytes(data []byte) (*Settings, error) {
161		settings := defaultSettings()
162		dec := json.NewDecoder(bytes.NewReader(data))
163		dec.DisallowUnknownFields()
164		if err := dec.Decode(settings); err != nil {
165			return nil, fmt.Errorf("parsing settings: %w", err)
166		}
167		return settings, nil
168	}
169	
170	// mergeV2Override applies local overrides on top of an existing Settings
171	// value. Field-level merge semantics: only fields explicitly present in
172	// the override JSON change the base.
173	//
174	// For now this delegates to a full reparse of the local file and replaces
175	// top-level groups wholesale. That is enough for the local-override use
176	// cases in the codebase today (toggling log level, enabling local_dev).
177	// More granular per-field merging can be added when a real call site needs
178	// it; the legacy code only got more granular for redaction/PII fields,
179	// and we will revisit that if the ergonomics become a problem.
180	func mergeV2Override(base *Settings, data []byte) error {
181		override, err := parseV2Bytes(data)
182		if err != nil {
183			return err
184		}
185	
186		var presence map[string]json.RawMessage
187		if err := json.Unmarshal(data, &presence); err != nil {
188			return fmt.Errorf("parsing local settings: %w", err)
189		}
190	
191		if _, ok := presence["enabled"]; ok {
192			base.Enabled = override.Enabled
193		}
194		if _, ok := presence["local_dev"]; ok {
195			base.LocalDev = override.LocalDev
196		}
197		if _, ok := presence["logging"]; ok {
198			base.Logging = override.Logging
199		}
200		if _, ok := presence["checkpoints"]; ok {
201			base.Checkpoints = override.Checkpoints
202		}
203		if _, ok := presence["hooks"]; ok {
204			base.Hooks = override.Hooks
205		}
206		if _, ok := presence["features"]; ok {
207			base.Features = override.Features
208		}
209		if _, ok := presence["redaction"]; ok {
210			base.Redaction = override.Redaction
211		}
212		if _, ok := presence["telemetry"]; ok {
213			base.Telemetry = override.Telemetry
214		}
215		if _, ok := presence["summary_generation"]; ok {
216			base.SummaryGeneration = override.SummaryGeneration
217		}
218		return nil
219	}
220	
221	// defaultSettings returns the zero-value Settings with documented defaults
222	// applied (Schema = 2, Enabled = true). Callers should treat this as the
223	// starting point before parsing a file or merging overrides.
224	func defaultSettings() *Settings {
225		return &Settings{
226			Schema:  CurrentSchemaVersion,
227			Enabled: true,
228		}
229	}
230	
231	// synthesizeFromLegacy maps an EntireSettings into a Settings, encoding the
232	// legacy → v2 migration. This is the single source of truth for the
233	// translation and is reused by `entire migrate-config`.
234	//
235	// Mappings:
236	//   - strategy_options.checkpoints_version=2 OR checkpoints_v2=true
237	//     → Checkpoints.Primary.Type = "v2"
238	//   - otherwise → Checkpoints.Primary.Type = "v1"
239	//   - strategy_options.gmeta=true → append {type: "gmeta"} to Mirrors
240	//   - strategy_options.checkpoint_remote → Checkpoints.Remote
241	//   - strategy_options.full_transcript_generation_retention_days
242	//     → Checkpoints.FullTranscriptRetentionDays
243	//   - strategy_options.filtered_fetches → Checkpoints.FilteredFetches
244	//   - strategy_options.push_sessions (explicit) → Checkpoints.PushSessions
245	//   - strategy_options.summarize.enabled → Features.Summarize
246	//   - log_level → Logging.Level
247	//   - sign_checkpoint_commits → Checkpoints.SignCommits
248	//   - commit_linking → Hooks.CommitLinking
249	//   - absolute_git_hook_path → Hooks.AbsoluteGitHookPath
250	//   - external_agents → Features.ExternalAgents
251	//   - vercel → Features.Vercel
252	//   - summary_generation.{provider,model} + summary_timeout_seconds
253	//     → SummaryGeneration.{Provider,Model,TimeoutSeconds}
254	//
255	// Dropped (no v2 destination):
256	//   - push_v2_refs (was a dual-write transition knob; v2 ref pushes are now
257	//     a property of the v2 backend's CheckpointSyncer, not a settings flag)
258	//   - strategy (deprecated tolerator field)
259	func synthesizeFromLegacy(s *EntireSettings) *Settings {
260		if s == nil {
261			return defaultSettings()
262		}
263	
264		out := &Settings{
265			Schema:   CurrentSchemaVersion,
266			Enabled:  s.Enabled,
267			LocalDev: s.LocalDev,
268			Logging: LoggingConfig{
269				Level: s.LogLevel,
270			},
271			Hooks: HooksConfig{
272				CommitLinking:       s.CommitLinking,
273				AbsoluteGitHookPath: s.AbsoluteGitHookPath,
274			},
275			Features: FeaturesConfig{
276				Summarize:      s.IsSummarizeEnabled(),
277				ExternalAgents: s.ExternalAgents,
278				Vercel:         s.Vercel,
279			},
280			Redaction: s.Redaction,
281			Telemetry: s.Telemetry,
282		}
283	
284		out.Checkpoints = synthesizeCheckpointsConfig(s)
285	
286		if hasSummaryGeneration(s) {
287			out.SummaryGeneration = &SummaryGenerationConfig{
288				TimeoutSeconds: s.SummaryTimeoutSeconds,
289			}
290			if s.SummaryGeneration != nil {
291				out.SummaryGeneration.Provider = s.SummaryGeneration.Provider
292				out.SummaryGeneration.Model = s.SummaryGeneration.Model
293			}
294		}
295	
296		return out
297	}
298	
299	// synthesizeCheckpointsConfig builds the v2 Checkpoints group from the
300	// legacy EntireSettings. Split out for readability since the mapping pulls
301	// from both top-level fields and the strategy_options soup.
302	func synthesizeCheckpointsConfig(s *EntireSettings) CheckpointsConfig {
303		cfg := CheckpointsConfig{
304			Primary:                     BackendConfig{Type: legacyPrimaryBackend(s)},
305			Remote:                      s.GetCheckpointRemote(),
306			FullTranscriptRetentionDays: legacyFullTranscriptRetention(s),
307			SignCommits:                 s.SignCheckpointCommits,
308			FilteredFetches:             s.IsFilteredFetchesEnabled(),
309			PushSessions:                legacyPushSessions(s),
310		}
311	
312		if legacyGmetaEnabled(s) {
313			cfg.Mirrors = append(cfg.Mirrors, BackendConfig{Type: BackendTypeGmeta})
314		}
315	
316		return cfg
317	}
318	
319	// legacyPrimaryBackend returns "v2" if either checkpoints_version or
320	// checkpoints_v2 enables v2 in the legacy settings, "v1" otherwise.
321	func legacyPrimaryBackend(s *EntireSettings) string {
322		if s.IsCheckpointsV2Enabled() {
323			return BackendTypeV2
324		}
325		return BackendTypeV1
326	}
327	
328	// legacyGmetaEnabled checks the legacy strategy_options.gmeta flag. The
329	// flag itself does not exist on this branch yet (it ships with the gmeta
330	// mainport), but the synthesizer recognizes it ahead of time so settings
331	// files written by that branch round-trip cleanly through Phase 0.
332	func legacyGmetaEnabled(s *EntireSettings) bool {
333		if s.StrategyOptions == nil {
334			return false
335		}
336		val, ok := s.StrategyOptions["gmeta"].(bool)
337		return ok && val
338	}
339	
340	// legacyFullTranscriptRetention returns the configured retention only when
341	// the legacy key is explicitly set; the legacy accessor returns a default
342	// when unset, which we suppress here so the v2 file stays minimal.
343	func legacyFullTranscriptRetention(s *EntireSettings) int {
344		if s.StrategyOptions == nil {
345			return 0
346		}
347		if _, ok := s.StrategyOptions["full_transcript_generation_retention_days"]; !ok {
348			return 0
349		}
350		return s.GetFullTranscriptGenerationRetentionDays()
351	}
352	
353	// legacyPushSessions extracts the explicit push_sessions boolean if set;
354	// otherwise returns nil so the v2 file stays minimal. The legacy semantics
355	// were "explicit false disables, otherwise default behavior", which we
356	// preserve by using a *bool here.
357	func legacyPushSessions(s *EntireSettings) *bool {
358		if s.StrategyOptions == nil {
359			return nil
360		}
361		val, ok := s.StrategyOptions["push_sessions"]
362		if !ok {
363			return nil
364		}
365		b, ok := val.(bool)
366		if !ok {
367			return nil
368		}
369		return &b
370	}
371	
372	// hasSummaryGeneration reports whether any summary-generation field on the
373	// legacy settings is non-default. Used to decide whether to allocate the
374	// v2 SummaryGenerationConfig at all (vs. leaving it nil).
375	func hasSummaryGeneration(s *EntireSettings) bool {
376		if s.SummaryGeneration != nil && (s.SummaryGeneration.Provider != "" || s.SummaryGeneration.Model != "") {
377			return true
378		}
379		return s.SummaryTimeoutSeconds > 0
380	}
381

