		t.Fatalf("Primary.Type = %q, want v2 (synthesized from main)", got.Checkpoints.Primary.Type)
	}
	if got.Logging.Level != debugLevel {
		t.Fatalf("Logging.Level = %q, want %q (from v2 local)", got.Logging.Level, debugLevel)
	}
}

