37	// LoadV2 loads settings as the v2 shape. Files declaring "schema": 2 are
38	// parsed natively; older files are loaded via the legacy parser and
39	// synthesized. Mixed shapes (one file v2, one legacy) are supported: the
40	// legacy file is translated field-by-field on top of the v2 base.
41	//
42	// Returns Settings with documented defaults if neither settings file exists.
43	// Validates the result before returning so semantic errors surface at load time.
44	func LoadV2(ctx context.Context) (*Settings, error) {
45		mainAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
46		if err != nil {
47			mainAbs = EntireSettingsFile
48		}
49		localAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
50		if err != nil {
51			localAbs = EntireSettingsLocalFile
52		}
53	
54		mainData, mainErr := readSettingsFileIfExists(mainAbs)
55		if mainErr != nil {
56			return nil, fmt.Errorf("reading settings file: %w", mainErr)
57		}
58		localData, localErr := readSettingsFileIfExists(localAbs)
59		if localErr != nil {
60			return nil, fmt.Errorf("reading local settings file: %w", localErr)
61		}
62	
63		settings, err := buildSettings(mainData, localData, mainAbs, localAbs)
64		if err != nil {
65			return nil, err
66		}
67		if err := settings.Validate(); err != nil {
68			return nil, fmt.Errorf("settings invalid: %w", err)
69		}
70		return settings, nil
71	}
72	
73	// LoadV2FromBytes parses a single settings document from raw bytes.
74	// Accepts either schema-v2 JSON or legacy JSON; the shape is auto-detected
75	// via the schema field. No local-override merge is performed.
76	func LoadV2FromBytes(data []byte) (*Settings, error) {
77		if len(data) == 0 {
78			return defaultSettings(), nil
79		}
80		var (
81			settings *Settings
82			err      error
83		)
84		if isSchemaV2(data) {
85			settings, err = parseV2Bytes(data)
86		} else {
87			var legacy *EntireSettings
88			legacy, err = LoadFromBytes(data)
89			if err == nil {
90				settings = synthesizeFromLegacy(legacy)
91			}
92		}
93		if err != nil {
94			return nil, err
95		}
96		if err := settings.Validate(); err != nil {
97			return nil, fmt.Errorf("settings invalid: %w", err)
98		}
99		return settings, nil
100	}
101	
102	// buildSettings constructs the merged Settings from raw main and local
103	// bytes. Each file may independently be v2 or legacy; this is what makes
104	// incremental migration of the gitignored local override safe.
105	//
106	// When both files are legacy, we delegate to the legacy loadMergedSettings
107	// so the legacy granular-merge behavior (PII fields, summary_generation
108	// provider/model interaction) is preserved verbatim before synthesis.
109	func buildSettings(mainData, localData []byte, mainAbs, localAbs string) (*Settings, error) {
110		if mainData == nil && localData == nil {
111			return defaultSettings(), nil
112		}
113		if !isSchemaV2(mainData) && !isSchemaV2(localData) {
114			legacy, err := loadMergedSettings(mainAbs, localAbs)
