136	// buildBase parses the main file into a Settings, choosing between the v2
137	// parser and the legacy synthesizer based on shape.
138	func buildBase(data []byte) (*Settings, error) {
139		if data == nil {
140			return defaultSettings(), nil
141		}
142		if isSchemaV2(data) {
